 const authorFile=useRef<HTMLInputElement>(null),stateRef=useRef(s),busyRef=useRef(false),abort=useRef<AbortController|null>(null),alive=useRef(true),view=useRef<HTMLDivElement>(null),timer=useRef<ReturnType<typeof setTimeout>|null>(null);
 stateRef.current=s;
