 function resumeDraft(){try{const d=JSON.parse(s.drafts.active||'null');if(d?.type==='chapter'&&s.books.some(b=>b.id===d.bookId)&&d.value){setBookId(d.bookId);setChapterDraft(d.value);setSheet('chapterEdit')}else if(d?.type==='book'&&d.value){setBookDraft(d.value);setSheet('bookEdit')}else toast('这份草稿无法打开，已保存作品仍保留')}catch{toast('这份草稿无法打开，已保存作品仍保留')}}
