 function saveChapterDraft(){if(!book||!chapterDraft)return;if(!chapterDraft.title.trim()||!chapterDraft.text.trim()){toast('填写章节标题和正文');return}const old=book.chapters.find(c=>c.id===chapterDraft.id);const c={...chapterDraft,zh:old&&old.text!==chapterDraft.text&&old.zh===chapterDraft.zh?'':chapterDraft.zh,previous:old?{title:old.title,text:old.text,zh:old.zh}:undefined};patchBook(book.id,b=>({...b,contextDirty:true,summary:'',state:'',threads:'',chapters:old?b.chapters.map(x=>x.id===c.id?c:x):[...b.chapters,c]}));update(v=>({...v,drafts:{...v.drafts,active:''}}));setChapterId(c.id);setPage('reader');setSheet(null);toast('章节已保存，作者署名保持不变')}
 function pickAuthorAvatar(file:File|undefined){if(!file)return;if(!file.type.startsWith('image/')){toast('请选择图片');return}if(file.size>3*1024*1024){toast('头像请选择3MB以内图片');return}const reader=new FileReader();reader.onload=()=>{if(alive.current)update(v=>({...v,avatar:String(reader.result)}))};reader.onerror=()=>toast('图片读取失败，请重试');reader.readAsDataURL(file)}
 async function uploadCover(file:File|undefined){if(!file||!bookDraft)return;const b=bookDraft;await run('处理封面',async()=>{if(!file.type.startsWith('image/'))throw Error('请选择图片');if(file.size>15*1024*1024)throw Error('图片请控制在15MB以内');const image=await createImageBitmap(file);try{const scale=Math.min(1,1000/image.width,1400/image.height);const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));const ctx=canvas.getContext('2d');if(!ctx)throw Error('无法处理图片');ctx.fillStyle='#fff';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(image,0,0,canvas.width,canvas.height);setBookDraft({...b,cover:canvas.toDataURL('image/jpeg',.85)})}finally{image.close()}})}
