 function saveStyle(){if(!styleDraft.name.trim()||(!styleDraft.content.trim()&&!styleDraft.worldBookIds?.length)){toast('填写文风名称和参考内容');return}const d={...styleDraft,id:styleDraft.id||novelId()};update(v=>({...v,styles:v.styles.some(x=>x.id===d.id)?v.styles.map(x=>x.id===d.id?d:x):[...v.styles,d]}));setSheet(null);toast('文风已保存')}
