 function saveZone(){if(!zoneName.trim()){toast('先填写专区名称');return}const id=zoneId&&s.zones.some(z=>z.id===zoneId)?zoneId:novelId();const z={id,name:zoneName.trim(),spec:structuredClone(spec)};update(v=>({...v,zones:v.zones.some(x=>x.id===id)?v.zones.map(x=>x.id===id?z:x):[...v.zones,z]}));setZoneId(id);setSheet(null);setPage('zoneDetail')}
