 function sendComment(review=false){if(!book||!commentText.trim())return;const c:NovelComment={id:novelId(),author:s.pen,own:true,text:commentText.trim(),rating:review?rating:undefined,at:Date.now()};patchBook(book.id,b=>({...b,reviews:review?[...b.reviews,c]:b.reviews,chapters:review?b.chapters:b.chapters.map(k=>k.id===chapterId?{...k,comments:[...k.comments,c]}:k)}));setCommentText('')}
 async function fetchComments(review=false){if(!book)return;const target=book.id,cid=chapterId;await run('生成读者互动',async signal=>{const rows=await generateNovelComments(book,review?undefined:cid,6,stateRef.current,signal);patchBook(target,b=>({...b,reviews:review?[...b.reviews,...rows]:b.reviews,chapters:review?b.chapters:b.chapters.map(c=>c.id===cid?{...c,comments:[...c.comments,...rows]}:c)}))})}
