 const IconButton=({label,children,onClick}:{label:string;children:ReactNode;onClick:()=>void})=><button className="nn-icon" aria-label={label} onClick={onClick}>{children}</button>;
 const Button=({children,onClick,primary=false,disabled=false}:{children:ReactNode;onClick:()=>void;primary?:boolean;disabled?:boolean})=><button disabled={disabled||!!busy} className={'nn-btn'+(primary?' primary':'')} onClick={onClick}>{children}</button>;
 const Title=({children,action}:{children:ReactNode;action?:ReactNode})=><div className="nn-row nn-section"><h3>{children}</h3>{action}</div>;
 const Empty=({children}:{children:ReactNode})=><div className="nn-empty"><BookOpen size={30}/><p>{children}</p></div>;
 const Pills=({values,selected,onChange}:{values:string[];selected:string[];onChange:(v:string[])=>void})=><div className="nn-chips">{values.map(t=><button key={t} className={'nn-pill'+(selected.includes(t)?' on':'')} onClick={()=>onChange(toggle(selected,t))}>{t}</button>)}</div>;
 const styleLabel=(b:NovelBook)=>b.styleSnapshot?.name||styles.find(x=>x.id===b.spec.styleIds[0])?.name||'自由叙述';
 const name=(id:string)=>id==='user'?'我':characters.find(c=>c.id===id)?.name||'已移除人物';
